INSERT INTO `ticket` VALUES (1,'Data integrity issue found in order-service','order-service appears to have written inconsistent data during a recent batch job, affecting 227 records affected.',1,NULL,'RESOLVED','HIGH','2026-07-23 23:13:38','2026-07-24 08:02:14','train'),(2,'order-service clients receiving 429 errors','order-service is rejecting a portion of traffic after exceeding 2781 requests/sec, the configured rate limit.',1,NULL,'RESOLVED','HIGH','2026-03-27 07:42:01','2026-03-27 09:34:13','train'),(3,'search-service pointing to wrong downstream endpoint','search-service is using an outdated configuration value, resulting in 47% of requests misrouted to an incorrect endpoint.',2,NULL,'RESOLVED','LOW','2026-04-10 09:06:38','2026-04-10 11:00:02','train'),(4,'NullPointerException crashing notification-service','Stack traces indicate an unhandled NPE in notification-service, triggered by malformed input on certain endpoints.',3,NULL,'RESOLVED','HIGH','2026-06-07 11:47:39','2026-06-07 17:20:39','train'),(5,'Thread deadlock detected in notification-service','notification-service has become unresponsive; monitoring shows 16 threads blocked for an extended period with no progress.',3,NULL,'RESOLVED','HIGH','2026-09-04 14:35:56','2026-09-04 19:23:20','train'),(6,'notification-service rejecting requests due to rate limiting','Client integrations are hitting notification-service\'s rate limiter, sustained load of 4732 requests/sec exceeding the threshold.',3,NULL,'RESOLVED','LOW','2026-04-16 02:14:04','2026-04-16 03:22:28','train'),(7,'notification-service rejecting valid JWT tokens','notification-service is rejecting valid credentials for a subset of users, with 457 failed login attempts recorded in the last hour.',3,NULL,'RESOLVED','LOW','2026-06-27 08:04:16','2026-06-27 10:58:52','train'),(8,'Suspected memory leak in payment-service','Heap dumps from payment-service show retained objects growing over time, consistent with a memory leak at roughly 48 MB/hour.',4,NULL,'RESOLVED','MEDIUM','2026-03-26 00:39:12','2026-03-26 09:14:36','train'),(9,'Race condition suspected in order-service','Load testing with 107 concurrent requests revealed a race condition in order-service\'s update logic, leading to data inconsistency.',1,NULL,'RESOLVED','HIGH','2026-03-15 12:51:26','2026-03-15 21:41:14','train'),(10,'payment-service database connection pool exhausted','payment-service is failing to acquire new database connections; pool usage has reached 106 active connections, at capacity.',4,NULL,'RESOLVED','LOW','2026-06-27 13:01:24','2026-06-27 20:08:36','train'),(11,'Intermittent timeout errors on auth-service','Users are reporting that auth-service times out intermittently during peak hours. Average response latency has spiked to 1457ms, well above the expected threshold.',5,NULL,'RESOLVED','MEDIUM','2026-03-28 13:00:57','2026-03-28 16:37:33','train'),(12,'payment-service API response time exceeding 3608ms','Users are reporting that payment-service times out intermittently during peak hours. Average response latency has spiked to 3608ms, well above the expected threshold.',4,NULL,'RESOLVED','MEDIUM','2026-05-11 20:02:00','2026-05-11 23:20:00','train'),(13,'notification-service rejecting requests due to rate limiting','notification-service is rejecting a portion of traffic after exceeding 796 requests/sec, the configured rate limit.',3,NULL,'RESOLVED','MEDIUM','2026-06-30 21:19:31','2026-06-30 22:59:07','train'),(14,'notification-service clients receiving 429 errors','Client integrations are hitting notification-service\'s rate limiter, sustained load of 440 requests/sec exceeding the threshold.',3,NULL,'RESOLVED','MEDIUM','2026-06-17 06:25:18','2026-06-17 07:58:18','train'),(15,'Rate limit threshold breached on notification-service','notification-service is rejecting a portion of traffic after exceeding 746 requests/sec, the configured rate limit.',3,NULL,'RESOLVED','MEDIUM','2026-05-23 20:40:45','2026-05-23 22:19:09','train'),(16,'search-service failing to reach external dependency','search-service depends on an external API that is currently returning errors at a 69% error rate, causing downstream failures.',2,NULL,'RESOLVED','HIGH','2026-04-12 18:13:42','2026-04-12 21:08:54','train'),(17,'Configuration drift causing search-service failures','A misconfigured property in search-service is causing 27% of requests misrouted, following the last deployment.',2,NULL,'RESOLVED','MEDIUM','2026-07-04 05:49:42','2026-07-04 08:26:18','train'),(18,'notification-service unable to acquire DB connections under load','Database connection pool for notification-service is maxed out at 84 active connections, causing request queuing and failures.',3,NULL,'RESOLVED','HIGH','2026-05-19 16:49:05','2026-05-19 20:01:05','train'),(19,'auth-service clients receiving 429 errors','A traffic spike pushed auth-service to 4904 requests/sec, triggering rate-limit rejections for legitimate users.',5,NULL,'RESOLVED','MEDIUM','2026-08-15 02:08:50','2026-08-15 03:28:38','train'),(20,'NullPointerException crashing search-service','A null reference in the request-handling path of search-service is causing intermittent crashes, observed 21 times in the last hour.',2,NULL,'RESOLVED','MEDIUM','2026-04-14 13:48:59','2026-04-14 18:54:23','train'),(21,'Rate limit threshold breached on auth-service','Client integrations are hitting auth-service\'s rate limiter, sustained load of 2615 requests/sec exceeding the threshold.',5,NULL,'RESOLVED','MEDIUM','2026-05-17 02:49:44','2026-05-17 04:11:56','train'),(22,'payment-service throwing NPE on certain requests','Stack traces indicate an unhandled NPE in payment-service, triggered by malformed input on certain endpoints.',4,NULL,'RESOLVED','HIGH','2026-05-19 17:26:01','2026-05-19 20:16:25','train'),(23,'notification-service producing inconsistent results under parallel load','Under approximately 91 concurrent requests, notification-service is producing inconsistent results, suggesting a race condition in shared state handling.',3,NULL,'RESOLVED','MEDIUM','2026-05-03 13:23:54','2026-05-03 21:43:42','train'),(24,'Configuration drift causing order-service failures','A misconfigured property in order-service is causing 21% of requests misrouted, following the last deployment.',1,NULL,'RESOLVED','MEDIUM','2026-07-19 06:44:21','2026-07-19 08:53:57','train'),(25,'Intermittent timeout errors on notification-service','Multiple retries observed for notification-service calls; timeout threshold of 2967ms is being breached repeatedly since this morning.',3,NULL,'RESOLVED','HIGH','2026-08-24 16:08:14','2026-08-24 20:20:14','train'),(26,'Race condition suspected in payment-service','Under approximately 82 concurrent requests, payment-service is producing inconsistent results, suggesting a race condition in shared state handling.',4,NULL,'RESOLVED','MEDIUM','2026-08-07 14:27:04','2026-08-07 22:09:40','train'),(27,'notification-service writing malformed data','An investigation into notification-service found 292 records affected with corrupted or malformed fields, likely due to a serialization bug.',3,NULL,'RESOLVED','HIGH','2026-04-06 02:16:20','2026-04-06 10:51:08','train'),(28,'auth-service database connection pool exhausted','Database connection pool for auth-service is maxed out at 56 active connections, causing request queuing and failures.',5,NULL,'RESOLVED','HIGH','2026-04-08 21:36:03','2026-04-09 05:13:15','train'),(29,'search-service host running low on disk space','Log rotation failed on search-service\'s host, allowing disk usage to climb to 87% disk used before the alert fired.',2,NULL,'RESOLVED','MEDIUM','2026-09-02 06:38:04','2026-09-02 09:18:52','train'),(30,'NullPointerException crashing payment-service','A null reference in the request-handling path of payment-service is causing intermittent crashes, observed 27 times in the last hour.',4,NULL,'RESOLVED','MEDIUM','2026-04-13 09:41:36','2026-04-13 11:56:36','train'),(31,'search-service API response time exceeding 5455ms','Users are reporting that search-service times out intermittently during peak hours. Average response latency has spiked to 5455ms, well above the expected threshold.',2,NULL,'RESOLVED','MEDIUM','2026-08-02 06:52:54','2026-08-02 12:22:18','train'),(32,'Suspected memory leak in notification-service','notification-service memory consumption is growing at approximately 352 MB/hour, eventually triggering OOM restarts.',3,NULL,'RESOLVED','HIGH','2026-07-14 13:24:48','2026-07-15 13:05:00','train'),(33,'auth-service writing malformed data','Data validation checks flagged 101 records affected in auth-service as corrupted, requiring manual reconciliation.',5,NULL,'RESOLVED','HIGH','2026-06-04 14:11:13','2026-06-04 21:20:49','train'),(34,'Spike in authentication failures on search-service','Following a recent deployment, search-service is failing to validate JWT tokens correctly, resulting in 423 failed login attempts.',2,NULL,'RESOLVED','HIGH','2026-04-02 03:48:18','2026-04-02 04:49:30','train'),(35,'Intermittent timeout errors on auth-service','Monitoring shows auth-service response latency crossing 3698ms for a subset of requests, causing downstream failures in dependent services.',5,NULL,'RESOLVED','MEDIUM','2026-04-25 13:26:04','2026-04-25 16:34:28','train'),(36,'Spike in authentication failures on search-service','Following a recent deployment, search-service is failing to validate JWT tokens correctly, resulting in 201 failed login attempts.',2,NULL,'RESOLVED','HIGH','2026-08-19 04:56:32','2026-08-19 07:07:56','train'),(37,'Misconfigured environment variable breaking auth-service','auth-service is using an outdated configuration value, resulting in 13% of requests misrouted to an incorrect endpoint.',5,NULL,'RESOLVED','HIGH','2026-06-14 17:41:53','2026-06-14 19:16:05','train'),(38,'Rate limit threshold breached on search-service','A traffic spike pushed search-service to 2368 requests/sec, triggering rate-limit rejections for legitimate users.',2,NULL,'RESOLVED